```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved grant: record the input this call received in the shared store.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value, not a trap;
        // it is reported as zero characters fetched.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat: {} chars fetched at {}", fetched, seconds);
        let notified = notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
